    for group in groups:
        if group['group_id'] == group_id:
            group_members = group['members']
            break
    payer_email = expense['payer']['email']
    receiver_email = next(member['email'] for member in group_members if member['email'] != payer_email)
    if payer_email == 'paul_mill@gmail.com' or receiver_email == 'paul_mill@gmail.com':
