Code:
```python
receivers = {}

for expense in expenses:
    group_id = expense['group_id']
    for group in groups:
        if group['group_id'] == group_id:
            group_members = group['members']
            break
    payer_email = expense['payer']['email']
    receivers[expense['expense_id']] = [member['email'] for member in group_members if member['email'] != payer_email]

for expense_id, receiver_emails in receivers.items():
    print(f"Expense ID: {expense_id}, Receivers: {receiver_emails}")
